#!/usr/bin/env python3
"""Minimal local DNS-over-HTTPS (HTTP/2) server for dnsperf testing.

Serves application/dns-message responses over HTTP/2 GET and POST,
with a self-signed TLS context. Answers every query with a synthetic
DNS response (NOERROR, echo id/question, 127.0.0.1 A or ::1 AAAA).
"""
import argparse
import base64
import socket
import ssl
import struct
import sys
import threading

from h2.config import H2Configuration
from h2.connection import H2Connection
from h2.events import (
    ConnectionTerminated, RequestReceived, StreamEnded, StreamReset,
    WindowUpdated, DataReceived,
)


def build_dns_response(query: bytes) -> bytes:
    if len(query) < 12:
        return query
    flags = query[2] | 0x80  # QR
    qd = struct.unpack("!H", query[4:6])[0]
    # header: id, flags(rd+qr), qd=1, an=1, ns=0, ar=0
    header = query[:2] + struct.pack("!HHHHH", flags, qd, 1, 0, 0)
    # parse question
    pos = 12
    qname = b""
    while pos < len(query):
        ln = query[pos]
        if ln == 0:
            pos += 1
            break
